problems.answer:
function solve(initialBalance, operations) {
  class Wallet {
    constructor(balance) {
      this.balance = balance;
    }

    deposit(amount) {
      this.balance += amount;
    }

    withdraw(amount) {
      if (amount <= this.balance) {
        this.balance -= amount;
      }
    }
  }

  const wallet = new Wallet(initialBalance);
  const balances = [];
  for (const operation of operations) {
    if (operation.type === "deposit") {
      wallet.deposit(operation.amount);
    } else {
      wallet.withdraw(operation.amount);
    }
    balances.push(wallet.balance);
  }
  return balances;
}

function solve(values) {
